/**
 * The Elitea docs site: Astro Starlight, static output.
 *
 * One build per serving target, chosen by DOCS_BASE: `/docs/` for the web
 * image (nginx, apps/elitea-web/nginx/spa.conf) and `/elitea-platform/` for
 * GitHub Pages (.github/workflows/docs-pages.yml). Pages, links and assets
 * all resolve under that base, so the same source serves both.
 *
 * Search is Pagefind, indexed from the built HTML at build time: no index is
 * committed and nothing is generated by hand.
 */
import starlight from '@astrojs/starlight';
import type { StarlightUserConfig } from '@astrojs/starlight/types';
import { defineConfig, passthroughImageService } from 'astro/config';
import starlightSidebarTopics from 'starlight-sidebar-topics';

import { nav, type NavGroup, type NavTab } from './src/nav';
import { rehypeBaseLinks } from './src/plugins/rehype-base-links';
import { remarkDocsComponents } from './src/plugins/remark-docs-components';
import { remarkMermaid } from './src/plugins/remark-mermaid';

const base = process.env['DOCS_BASE'] ?? '/docs/';

type SidebarItem = NonNullable<StarlightUserConfig['sidebar']>[number];

/** Each nav tab's icon in the topic switcher (Starlight's built-in set). */
const TOPIC_ICONS: Record<string, string> = {
  Home: 'open-book',
  'Getting started': 'rocket',
  Development: 'laptop',
  Guides: 'document',
  Integrations: 'puzzle',
  Deployment: 'seti:docker',
  Admin: 'setting',
};

function pageItem(slug: string, label: string): SidebarItem {
  return slug === '' ? { label, link: '/' } : { label, slug };
}

function groupItem(group: NavGroup, collapsed = false): SidebarItem {
  return {
    label: group.title,
    collapsed,
    items: [
      ...group.pages.map((page) => pageItem(page.slug, page.title)),
      ...(group.groups ?? []).map((child) => groupItem(child, true)),
    ],
  };
}

function topic(tab: NavTab) {
  const first = tab.groups[0]?.pages[0];
  return {
    label: tab.title,
    link: first === undefined || first.slug === '' ? '/' : `/${first.slug}/`,
    icon: TOPIC_ICONS[tab.title] ?? 'document',
    items: tab.groups.map((group) => groupItem(group)),
  };
}

export default defineConfig({
  base,
  site: process.env['DOCS_SITE'],
  trailingSlash: 'ignore',
  build: { format: 'directory' },
  // Screenshots are committed as sized webp and the logos are SVG: nothing
  // to transform, so no native image toolchain in the build.
  image: { service: passthroughImageService() },
  markdown: {
    remarkPlugins: [remarkDocsComponents, remarkMermaid],
    rehypePlugins: [[rehypeBaseLinks, { base }]],
  },
  integrations: [
    starlight({
      title: 'Elitea AI Docs',
      description: 'Chat, agents, pipelines, toolkits and platform administration in one workspace.',
      logo: {
        light: './src/assets/elitea-lockup-on-light.svg',
        dark: './src/assets/elitea-lockup-on-dark.svg',
        replacesTitle: true,
      },
      favicon: '/favicon.svg',
      customCss: ['./src/styles/theme.css'],
      lastUpdated: false,
      pagination: true,
      tableOfContents: { minHeadingLevel: 2, maxHeadingLevel: 3 },
      components: {
        MarkdownContent: './src/components/overrides/MarkdownContent.astro',
      },
      plugins: [starlightSidebarTopics(nav.map(topic))],
    }),
  ],
});
